```python
def camel_to_snake(identifier: str) -> str:
    """
    Convert a camelCase or PascalCase identifier to snake_case.

    Examples:
    - "camelCase" -> "camel_case"
    - "PascalCaseName" -> "pascal_case_name"
    - "x" -> "x"
    """
    if not identifier:
        return identifier

    result = []
    for i, char in enumerate(identifier):
        if char.isupper():
            # Insert underscore before uppercase letters (except at start)
            if i != 0 and identifier[i - 1].islower():
                result.append('_')
            # Also handle cases where there are consecutive uppercase letters
            # like "JSONData" -> "json_data"
            elif i != 0 and identifier[i - 1].isupper():
                # Look ahead to see if we should split here
                if i + 1 < len(identifier) and identifier[i + 1].islower():
                    result.append('_')
            result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)
