def compress_whitespace(s):
    result = []
    in_whitespace = False

    for char in s:
        if char.isspace():
            if not in_whitespace:
                result.append(' ')
                in_whitespace = True
        else:
            result.append(char)
            in_whitespace = False

    compressed = ''.join(result).strip()
    return compressed


