```python
def count_islands(grid):
    """
    Count groups of horizontally or vertically connected 1s in a grid.

    Args:
        grid (list[list[int]]): 2D list of 0s and 1s

    Returns:
        int: Number of distinct islands
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    def dfs(r, c):
        """Perform depth-first search to mark all cells in this island."""
        stack = [(r, c)]

        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]:
                continue
            visited[cr][cc] = True

            for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 1 and not visited[nr][nc]:
                        stack.append((nr, nc))

    island_count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                dfs(r, c)
                island_count += 1

    return island_count


