def longest_run(lst):
    if not lst:
        return 0

    max_run = 1
    current_run = 1
    prev = lst[0]

    for item in lst[1:]:
        if item == prev:
            current_run += 1
            if current_run > max_run:
                max_run = current_run
        else:
            current_run = 1
            prev = item

    return max_run
```

