def nth_prime(n):
    """Return the n-th prime number (1-indexed)."""
    if n < 1:
        raise ValueError("n must be a positive integer")

    primes = []
    candidate = 2

    while len(primes) < n:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1

    return primes[-1]
```

