Below is a clean C++ implementation of a suffix array with substring and suffix search capabilities. This version uses the prefix-doubling algorithm (O(n log n)) for simplicity and clarity while remaining practical for most applications. An alternative SA-IS implementation would improve construction time to O(n), but the prefix-doubling approach is easier to understand and sufficient for most use cases.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

class SuffixArray {
public:
    SuffixArray(const std::string& text) : s(text + '\0') {
        n = s.size();
        build_suffix_array();
        build_lcp_array()
    }

    // Returns the range of suffixes that match the pattern
    // If no match, returns {0, 0}
    std::pair<int, int> substring_search(const std::string& pattern) const {
        int left = 0, right = n;
        // Find the left bound
        while (left < right) {
            int mid = (left + right) / 2;
            if (compare_substring(sa[mid], pattern) < 0) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        int start = left;
        right = n;
        // Find the right bound
        while (left < right) {
            int mid = (left + right) / 2;
            if (compare_substring(sa[mid], pattern) <= 0) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        int end = left;
        if (start >= end) return {0, 0};
        return {start, end};
    }

    // Returns true if pattern is a suffix of s
    bool suffix_search(const std::string& pattern) const {
        return s.size() >= pattern.size() &&
               std::equal(pattern.rbegin(), pattern.rend(), s.rbegin());
    }

    // Accessors
    const std::vector<int>& get_sa() const { return sa; }
    const std::vector<int>& get_lcp() const { return lcp; }

private:
    std::string s;
    int n;
    std::vector<int> sa;    // suffix array
    std::vector<int> rank;  // rank array
    std::vector<int> tmp;
    std::vector<int> lcp;   // longest common prefix array

    // O(1) character access with sentinel
    char char_at(int i) const {
        return (i < n) ? s[i] : '\0';
    }

    // Compare substring of s starting at pos with pattern
    int compare_substring(int pos, const std::string& pattern) const {
        int i = 0;
        while (i < pattern.size() && pos + i < s.size()) {
            if (s[pos + i] != pattern[i]) {
                return (unsigned char)s[pos + i] < (unsigned char)pattern[i] ? -1 : 1;
            }
            ++i;
        }
        return (i < pattern.size()) ? -1 : 0;
    }

    // Prefix-doubling suffix array construction
    void build_suffix_array() {
        sa.resize(n);
        rank.resize(n);
        tmp.resize(n);

        for (int i = 0; i < n; ++i) {
            sa[i] = i;
            rank[i] = s[i];
        }

        for (int k = 1; k < n; k *= 2) {
            auto compare_sa = [&](int i, int j) {
                if (rank[i] != rank[j]) return rank[i] < rank[j];
                int ri = (i + k < n) ? rank[i + k] : -1;
                int rj = (j + k < n) ? rank[j + k] : -1;
                return ri < rj;
            };
            std::sort(sa.begin(), sa.end(), compare_sa);

            tmp[sa[0]] = 0;
            for (int i = 1; i < n; ++i) {
                tmp[sa[i]] = tmp[sa[i-1]] + (compare_sa(sa[i-1], sa[i]) ? 1 : 0);
            }
            rank = tmp;
            if (rank[sa[n-1]] == n-1) break; // All ranks are distinct
        }
    }

    // Kasai's algorithm for building LCP array
    void build_lcp_array() {
        lcp.resize(n);
        std::vector<int> inv_sa(n);
        for (int i = 0; i < n; ++i) {
            inv_sa[sa[i]] = i;
        }
        int k = 0;
        for (int i = 0; i < n; ++i) {
            if (inv_sa[i] == 0) {
                lcp[0] = 0;
                continue;
            }
            int j = sa[inv_sa[i] - 1];
            while (i + k < s.size() && j + k < s.size() && s[i + k] == s[j + k]) {
                ++k;
            }
            lcp[inv_sa[i]] = k;
            if (k > 0) --k;
        }
    }
};
```

## Usage Example

```cpp
int main() {
    std::string text = "banana";
    SuffixArray SA(text);

    // Substring search
    std::string pattern = "ana";
    auto range = SA.substring_search(pattern);

    if (range.first != range.second) {
        std::cout << "Pattern found " << (range.second - range.first) << " times:\n";
        for (int i = range.first; i < range.second; ++i) {
            std::cout << "  Suffix at index " << SA.get_sa()[i] << ": ";
            std::cout << text.substr(SA.get_sa()[i]) << "\n";
        }
    } else {
        std::cout << "Pattern not found\n";
    }

    // Suffix check
    std::string suffix = "na";
    std::cout << "Is \"" << suffix << "\" a suffix? " 
              << std::boolalpha << SA.suffix_search(suffix) << "\n";
}
```

## Complexity Analysis

| Operation | Time Complexity | Space Complexity |
|-----------|-----------------|------------------|
| Build SA | O(n log n) | O(n) |
| Build LCP | O(n) | O(n) |
| Substring Search | O(m log n) | — |
| Suffix Check | O(x) where x = min(text size, pattern size) | — |

## Notes

- The suffix array includes a sentinel character (`'\0'`) appended to the end of the input text to ensure all suffixes are comparable.
- The `substring_search` method returns the range of suffixes that start with the given pattern. The range is half-open: `[start, end)`.
- The implementation uses the prefix-doubling algorithm for clarity. Production systems might prefer SA-IS or DC3 for linear construction time, though O(n log n) is acceptable for moderate string lengths.
- The LCP array enables faster range queries and finding distinct substrings, though it's not used in this basic suffix/substring check implementation.

This implementation is suitable for educational purposes and moderate-scale applications. For massive texts (hundreds of millions of characters), consider a more memory-efficient implementation or an external-memory suffix array variant.

Here is a simple C++ program that generates and prints the first 100 prime numbers using a basic trial division method:

```cpp
#include <iostream>
#include <vector>
#include <cmath>

// Function to check if a number is prime
bool isPrime(int num) {
    if (num < 2) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;

    int sqrtNum = static_cast<int>(std::sqrt(num));
    for (int i = 3; i <= sqrtNum; i += 2) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

// Main function to generate and print first 100 primes
int main() {
    std::vector<int> primes;
    int currentNum = 2;

    while (primes.size() < 100) {
        if (isPrime(currentNum)) {
            primes.push_back(currentNum);
        }
        ++currentNum;
    }

    // Output the prime numbers
    std::cout << "First 100 prime numbers:" << std::endl;
    for (size_t i = 0; i < primes.size(); ++i) {
        std::cout << primes[i];
        if (i != primes.size() - 1) {
            std::cout << ", ";
        }
    }
    std::cout << std::endl;

    return 0;
}
```

This program:
1. Uses a simple `isPrime` helper function with trial division
2. Generates primes iteratively until it has collected 100 primes
3. Stores them in a `std::vector`
4. Prints them in a comma-separated list

The time complexity is reasonable for generating only 100 primes, and the implementation uses only standard C++ without any external dependencies. Feel free to modify the output format or the size of primes to generate as needed.

