class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        visited = []

        rows = len(grid)
        cols = len(grid[0])

        for i in range(rows):
            if i % 2 == 0:
                # Even-indexed rows go right
                for j in range(cols):
                    visited.append(grid[i][j])
            else:
                # Odd-indexed rows go left
                for j in range(cols - 1, -1, -1):
                    visited.append(grid[i][j])

        # Skip every alternate cell (take even-indexed positions in the visited order)
        for idx, val in enumerate(visited):
            if idx % 2 == 0:
                result.append(val)

        return result

