class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)

        # Compute prefix sums for O(1) subarray sum queries
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        # Helper to compute sum of nums[l..r] inclusive
        def subarray_sum(l, r):
            return prefix[r + 1] - prefix[l]

        # Initialize DP table:
        # dp[i][j] = maximum sum using first i elements with j subarrays
        dp = [[float('-inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        # Iterate through array positions
        for i in range(1, n + 1):
            for sub in range(k + 1):
                # Initialize with not taking a subarray ending at position i-1
                dp[i][sub] = dp[i - 1][sub]

                # If we want to form a subarray ending at i-1,
                # we need at least m length and at least one subarray to use
                if sub > 0:
                    # Consider all possible lengths >= m
                    for length in range(m, min(i, n) + 1):
                        start = i - length
                        if start < 0:
                            break
                        dp[i][sub] = max(
                            dp[i][sub],
                            dp[start][sub - 1] + subarray_sum(start, i - 1)
                        )

        return dp[n][k]

