                if new_prod <= limit:
                    new_sum = sum_val + num  # even index contribution
                    new_odd[new_sum] = max(new_odd.get(new_sum, -1), new_prod)

            # Extend subsequences currently with odd length (next element goes to even position)
            for sum_val, prod_val in dp_odd.items():
                new_prod = prod_val * num
                if new_prod <= limit:
                    new_sum = sum_val - num  # odd index contribution (subtract)
                    new_even[new_sum] = max(new_even.get(new_sum, -1), new_prod)

            dp_even = new_even
            dp_odd = new_odd

        # Retrieve answer from both parity states
        answer_even = dp_even.get(k, -1)
        answer_odd = dp_odd.get(k, -1)

        return max(answer_even, answer_odd, -1)

