class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        """
        Find the length of the longest palindrome that can be formed by concatenating:
        (substring from s) + (substring from t)
        """

        max_len = 0
        n, m = len(s), len(t)

        # Generate all substrings of s (including empty)
        for i in range(n + 1):
            for j in range(i, n + 1):
                sub_s = s[i:j]  # substring from i (inclusive) to j (exclusive)

                # Generate all substrings of t (including empty)
                for p in range(m + 1):
                    for q in range(p, m + 1):
                        sub_t = t[p:q]

                        # Concatenate and check palindrome
                        candidate = sub_s + sub_t
                        if candidate == candidate[::-1]:
                            max_len = max(max_len, len(candidate))

        return max_len

