    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 1 if i == 2 else 2
    if n > 1:
        factors[n] = 1
    return list(factors.keys())

def find_primitive_root(p, factors_of_order):
    # Try candidates 2,3,... until find primitive root of order N
    for g in range(2, p):
        for q in factors_of_order:
            if pow(g, (p - 1) // q, p) == 1:
                break
        else:
            return g
    return None

